// Enhanced JSON Parser & Cleaner for Exam Generation
// Following n8n-automation-rules.md standards

try {
  const inputData = $input.first();
  if (!inputData || !inputData.json) {
    throw new Error('No input data received from AI generator');
  }

  let rawOutput = inputData.json.output;
  if (!rawOutput || typeof rawOutput !== 'string') {
    throw new Error('AI output is empty or not a string');
  }

  console.log('AI Response Preview:', rawOutput.substring(0, 200) + '...');

  // Clean and normalize the response
  rawOutput = rawOutput.trim();

  // Remove markdown code block wrappers
  const codeBlockPatterns = [
    /^```(?:json|JSON)?\s*\n([\s\S]*?)\n```$/m,
    /^```\s*\n([\s\S]*?)\n```$/m,
    /^```(?:json|JSON)?\s*([\s\S]*?)```$/m,
    /^```([\s\S]*?)```$/m
  ];

  for (const pattern of codeBlockPatterns) {
    const match = rawOutput.match(pattern);
    if (match) {
      rawOutput = match[1].trim();
      console.log('Removed code block wrapper');
      break;
    }
  }

  // Multiple JSON extraction strategies
  let jsonString = null;
  let extractionMethod = '';

  // Strategy 1: Balanced brace extraction
  const start = rawOutput.indexOf('{');
  if (start !== -1) {
    let braceCount = 0;
    let inString = false;
    let escapeNext = false;

    for (let i = start; i < rawOutput.length; i++) {
      const char = rawOutput[i];

      if (escapeNext) {
        escapeNext = false;
        continue;
      }

      if (char === '\\') {
        escapeNext = true;
        continue;
      }

      if (char === '"' && !escapeNext) {
        inString = !inString;
        continue;
      }

      if (!inString) {
        if (char === '{') {
          braceCount++;
        } else if (char === '}') {
          braceCount--;
          if (braceCount === 0) {
            jsonString = rawOutput.substring(start, i + 1);
            extractionMethod = 'balanced-braces';
            break;
          }
        }
      }
    }
  }

  // Strategy 2: First to last brace
  if (!jsonString) {
    const firstBrace = rawOutput.indexOf('{');
    const lastBrace = rawOutput.lastIndexOf('}');

    if (firstBrace !== -1 && lastBrace !== -1 && firstBrace < lastBrace) {
      jsonString = rawOutput.substring(firstBrace, lastBrace + 1);
      extractionMethod = 'first-last-brace';
    }
  }

  if (!jsonString) {
    throw new Error('No valid JSON structure found in AI response');
  }

  console.log(`JSON extracted using: ${extractionMethod}`);

  // Clean the JSON string
  jsonString = jsonString
    .trim()
    .replace(/^[^{]*/, '')
    .replace(/[^}]*$/, '')
    .replace(/\s*:\s*/g, ':')
    .replace(/\s*,\s*/g, ',')
    .replace(/[\x00-\x1f\x7f-\x9f]/g, '');

  // Parse JSON with error handling
  let parsedJSON;
  try {
    parsedJSON = JSON.parse(jsonString);
  } catch (parseError) {
    console.log('Initial JSON parse failed, attempting repairs...');

    // Fix common JSON issues
    const repairedJSON = jsonString
      .replace(/,(\s*[}\]])/g, '$1')  // Remove trailing commas
      .replace(/}(\s*){/g, '},$1{')   // Add missing commas
      .replace(/](\s*)\[/g, '],$1['); // Add missing commas

    try {
      parsedJSON = JSON.parse(repairedJSON);
      console.log('JSON successfully repaired and parsed');
    } catch (repairError) {
      throw new Error(`JSON parsing failed. Original: ${parseError.message}. Repair: ${repairError.message}`);
    }
  }

  // Validate JSON structure with support for different question types
  const errors = [];
  if (!parsedJSON.examId) errors.push('Missing examId field');
  if (!parsedJSON.subject) errors.push('Missing subject field');
  if (!parsedJSON.questions) errors.push('Missing questions field');

  if (!Array.isArray(parsedJSON.questions)) {
    errors.push('questions field must be an array');
  } else {
    parsedJSON.questions.forEach((question, index) => {
      if (!question.id) errors.push(`Question ${index + 1}: Missing id`);
      if (!question.question) errors.push(`Question ${index + 1}: Missing question text`);
      if (!question.type) errors.push(`Question ${index + 1}: Missing type`);

      // Validate based on question type
      if (question.type === 'mcq' || question.type === 'MCQ') {
        if (!Array.isArray(question.options) || question.options.length !== 4) {
          errors.push(`Question ${index + 1}: MCQ must have 4 options`);
        }
        if (!question.correctAnswer) {
          errors.push(`Question ${index + 1}: MCQ missing correctAnswer`);
        }
      } else if (question.type === 'structural') {
        if (!question.markingScheme || !Array.isArray(question.markingScheme)) {
          errors.push(`Question ${index + 1}: Structural question missing markingScheme array`);
        }
        if (!question.sampleAnswer) {
          errors.push(`Question ${index + 1}: Structural question missing sampleAnswer`);
        }
      }
    });
  }

  if (errors.length > 0) {
    throw new Error(`JSON validation failed: ${errors.join(', ')}`);
  }

  // Enhance and normalize the exam data with proper type handling
  const enhancedExam = {
    examId: parsedJSON.examId || `EXAM_${Date.now()}`,
    subject: parsedJSON.subject || 'Unknown Subject',
    level: parsedJSON.level || 'Unknown Level',
    difficulty: parsedJSON.difficulty || 'Medium',
    questionType: parsedJSON.questionType || 'Mixed',
    duration: parsedJSON.duration || 60,
    generatedAt: parsedJSON.generatedAt || new Date().toISOString(),
    totalQuestions: parsedJSON.questions ? parsedJSON.questions.length : 0,
    questions: []
  };

  if (Array.isArray(parsedJSON.questions)) {
    enhancedExam.questions = parsedJSON.questions.map((question, index) => {
      const baseQuestion = {
        id: question.id || (index + 1),
        topic: question.topic || 'General',
        type: question.type || 'mcq',
        question: question.question || '',
        marks: question.marks || 1,
        explanation: question.explanation || 'Explanation not provided',
        difficulty: question.difficulty || enhancedExam.difficulty
      };

      // Add type-specific fields
      if (question.type === 'mcq' || question.type === 'MCQ') {
        baseQuestion.options = Array.isArray(question.options) ? question.options : [];
        baseQuestion.correctAnswer = question.correctAnswer || 'A';
      } else if (question.type === 'structural') {
        baseQuestion.markingScheme = Array.isArray(question.markingScheme) ? question.markingScheme : [];
        baseQuestion.sampleAnswer = question.sampleAnswer || 'Sample answer not provided';
      }

      return baseQuestion;
    });
  }

  // Return success response
  return {
    json: {
      success: true,
      generatedQuestions: enhancedExam,
      metadata: {
        extractionMethod: extractionMethod,
        originalLength: rawOutput.length,
        parsedLength: jsonString.length,
        questionCount: enhancedExam.questions.length,
        processedAt: new Date().toISOString()
      }
    }
  };

} catch (error) {
  console.error('Parse & Clean JSON Error:', error.message);

  return {
    json: {
      success: false,
      error: error.message,
      errorType: 'JSON_PARSING_ERROR',
      timestamp: new Date().toISOString(),
      debugInfo: {
        inputType: typeof $input.first()?.json?.output,
        inputLength: $input.first()?.json?.output?.length || 0,
        hasInput: !!$input.first()?.json?.output
      }
    }
  };
}
